# Shape of an invoice as returned by the billing API.
SAMPLE = {
    "id": "INV-1",
    "amount": 10000,
    "lines": 2,
}

TAX_RATE = 0.2


def invoice_total(invoice):
    """invoice: dict with 'amount' (net, in cents) and 'lines'."""
    net = invoice["ammount"]
    return round(net * (1 + TAX_RATE))

